package com.bank.paging;

import java.util.*;
import java.util.logging.*;

public class PagingDemo {
    private static final Logger log = Logger.getLogger("Paging");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Vikram", 2500000),
            new Employee("Rohit", 1800000),
            new Employee("Sneha", 1500000),
            new Employee("Rajesh", 1200000),
            new Employee("Priya", 900000),
            new Employee("Anjali", 850000),
            new Employee("Amit", 700000)
        );
        EmployeePageService service = new EmployeePageService();

        List<Employee> page2 = service.page(employees, 2, 3); // second page, size 3
        log.info("Page 2 (earners 4-6):");
        page2.forEach(e -> log.info(() -> "  " + e.getName() + " = " + e.getSalary()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
        Employee(String name, double salary) { this.name = name;
        this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/EmployeePageService.java ───
class EmployeePageService {
    List<Employee> page(List<Employee> employees, int pageNumber, int pageSize) {
        long offset = (long) (pageNumber - 1) * pageSize;   // page 2 → offset 3
        return employees.stream()
            .sorted(Comparator.comparingDouble(Employee::getSalary).reversed()) // fix order
            .skip(offset)      // drop earlier pages
            .limit(pageSize)   // keep only this page
            .collect(java.util.stream.Collectors.toList());
    }
}
